package com.zy.zhangyun;

import android.app.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.util.concurrent.*;

public class ProjectActivity extends Activity {
  ApiClient api; TextView status; LinearLayout approvals; ExecutorService pool=Executors.newSingleThreadExecutor();
  public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_project);api=new ApiClient(this);status=findViewById(R.id.status);approvals=findViewById(R.id.approvals);findViewById(R.id.refresh).setOnClickListener(v->refresh());refresh();}
  void refresh(){status.setText("正在读取项目状态…");pool.execute(()->{try{JSONObject s=new JSONObject(api.get("/api/project/status"));JSONObject sv=s.getJSONObject("services"),m=s.getJSONObject("models");String text="服务状态\n对话："+sv.getString("chat")+"\nHTTPS："+sv.getString("https")+"\n语言模型："+sv.getString("language")+"\n语音模型："+sv.getString("voice")+"\n\n模型下载\nQwen3-TTS："+m.getJSONObject("voice").getInt("percent")+"%\nSenseVoice："+m.getJSONObject("asr").getInt("percent")+"%\n\n待审批："+s.getInt("pending_approvals");JSONArray list=new JSONObject(api.get("/api/project/approvals")).getJSONArray("approvals");runOnUiThread(()->show(text,list));}catch(Exception e){runOnUiThread(()->status.setText("无法读取项目状态，请检查服务器连接。"));}});}
  void show(String text,JSONArray list){status.setText(text);approvals.removeAllViews();if(list.length()==0){TextView empty=new TextView(this);empty.setText("暂无待审批项目");empty.setTextColor(Color.LTGRAY);approvals.addView(empty);return;}for(int i=0;i<list.length();i++)try{JSONObject item=list.getJSONObject(i);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(12,16,12,16);TextView label=new TextView(this);label.setText(item.getString("title")+"\n"+item.getString("detail")+"\n状态："+item.getString("status"));label.setTextColor(Color.WHITE);row.addView(label);if("pending".equals(item.getString("status"))){LinearLayout buttons=new LinearLayout(this);Button yes=new Button(this);yes.setText("批准");yes.setOnClickListener(v->decide(item.optInt("id"),"approved"));Button no=new Button(this);no.setText("拒绝");no.setOnClickListener(v->decide(item.optInt("id"),"rejected"));buttons.addView(yes);buttons.addView(no);row.addView(buttons);}approvals.addView(row);}catch(Exception ignored){}}
  void decide(int id,String value){pool.execute(()->{try{api.post("/api/project/approvals/"+id,"decision="+URLEncoder.encode(value,"UTF-8"));runOnUiThread(()->refresh());}catch(Exception ignored){}});}
}
